import { writeProjectFile } from "../_shared/deno-helpers.ts";

// Extends the same file from Day 1.3 and Day 2.3 with two more helpers.
await writeProjectFile("week2/generated/registration-helpers.ts", `// Week 2 — shared actions, checks, and unique-data helpers for the Register.html form.
import type { Page } from "@playwright/test";
import { expect } from "@playwright/test";

export async function fillRegistrationForm(page: Page, email: string) {
  await page.goto("https://demo.automationtesting.in/Register.html");

  await page.getByPlaceholder("First Name").fill("Ada");
  await page.getByPlaceholder("Last Name").fill("Lovelace");
  await page.locator("textarea").fill("123 Analytical Engine Way");
  await page.locator("input[type='email']").fill(email);
  await page.locator("input[type='tel']").fill("5551234567");

  await page.locator("input[value='FeMale']").check();
  await page.locator("#checkbox1").check();

  await page.locator("#Skills").selectOption({ label: "Java" });
  await page.locator("#country").selectOption("India");
}

export async function expectFormFilledCorrectly(page: Page, email: string) {
  await expect(page.locator("input[type='email']")).toHaveValue(email);
  await expect(page.getByPlaceholder("First Name")).toHaveValue("Ada");
  await expect(page).toHaveURL(/Register\\.html/);
}

// A fresh, collision-free email on every call.
export function uniqueEmail(): string {
  return "learner" + Math.random().toString(36).slice(2, 8) + "@example.com";
}

// Picks Male or FeMale at random and checks it via a dynamic XPath built from
// that choice — @value works here because both values are static markup, not
// something .fill() set at runtime (see Day 3.2 for why that distinction matters).
export async function pickAndCheckGender(page: Page): Promise<string> {
  const choice = Math.random() < 0.5 ? "Male" : "FeMale";
  const xpath = "//input[@value='" + choice + "']";
  await page.locator("xpath=" + xpath).check();
  return choice;
}
`.trim());

import { runSpec } from "../_shared/deno-helpers.ts"; // writeProjectFile already imported above

const specPath = "week2/generated/day3-reuse.spec.ts";

await writeProjectFile(specPath, `
import { test, expect } from "@playwright/test";
import { uniqueEmail, pickAndCheckGender } from "./registration-helpers";

test("run A gets its own unique data", async ({ page }) => {
  await page.goto("https://demo.automationtesting.in/Register.html");
  const email = uniqueEmail();
  await page.locator("input[type='email']").fill(email);
  await expect(page.locator("input[type='email']")).toHaveValue(email);
  await pickAndCheckGender(page);
});

test("run B gets a different unique value than run A", async ({ page }) => {
  await page.goto("https://demo.automationtesting.in/Register.html");
  const email = uniqueEmail();
  await page.locator("input[type='email']").fill(email);
  await expect(page.locator("input[type='email']")).toHaveValue(email);
  await pickAndCheckGender(page);
});
`.trim());

await runSpec(specPath);

